foreach(IFamily family in new IFamily[]{new PlainFamily(),new HtmlFamily()})
{var formatter=family.Formatter();var renderer=family.Renderer();Console.WriteLine(renderer.Render(formatter.Format("An")));}
try{_ = SourceFactory.Create("unknown");}catch(ArgumentException){Console.WriteLine("unsupported");}
Console.WriteLine(SourceFactory.Create("memory").Read());Console.WriteLine(SourceFactory.Create("file").Read());
interface IFormatter{string Format(string value);}interface IRenderer{string Render(string value);}
interface IFamily{IFormatter Formatter();IRenderer Renderer();}
class PlainFamily:IFamily{public IFormatter Formatter()=>new PlainFormatter();public IRenderer Renderer()=>new PlainRenderer();}
class HtmlFamily:IFamily{public IFormatter Formatter()=>new HtmlFormatter();public IRenderer Renderer()=>new HtmlRenderer();}
class PlainFormatter:IFormatter{public string Format(string s)=>"text:"+s;}
class PlainRenderer:IRenderer{public string Render(string s)=>"plain["+s+"]";}
class HtmlFormatter:IFormatter{public string Format(string s)=>System.Net.WebUtility.HtmlEncode(s);}
class HtmlRenderer:IRenderer{public string Render(string s)=>"<p>"+s+"</p>";}
interface ISource{string Read();}
class MemorySource:ISource{public string Read()=>"memory";}
class FileSource:ISource{public string Read()=>"file fixture";}
static class SourceFactory{public static ISource Create(string kind)=>kind switch{"memory"=>new MemorySource(),"file"=>new FileSource(),_=>throw new ArgumentException("unsupported")};}

